{
  "version": "0.1",
  "description": "Schema for AI Safety Evaluation Landscape Database",
  "lastUpdated": "2026-11-16",
  "fields": [
    {
      "name": "eval_id",
      "type": "string",
      "description": "Unique identifier (e.g., 'arc-autonomous-replication-2024')",
      "required": true
    },
    {
      "name": "name",
      "type": "string",
      "description": "Human-readable name",
      "required": true
    },
    {
      "name": "creator_org",
      "type": "string",
      "description": "Organization that created/published the eval",
      "required": true
    },
    {
      "name": "publication_date",
      "type": "string",
      "format": "date",
      "description": "Date first published/released",
      "required": true
    },
    {
      "name": "link",
      "type": "string",
      "format": "uri",
      "description": "Primary URL (paper, repo, blog post)",
      "required": true
    },
    {
      "name": "capability_categories",
      "type": "array",
      "items": {
        "type": "string",
        "enum": [
          "autonomous-replication",
          "deception",
          "situational-awareness",
          "CBRN",
          "cyber-offensive",
          "persuasion",
          "interpretability",
          "control",
          "robustness",
          "alignment",
          "multi-agent",
          "other"
        ]
      },
      "description": "One or more capability categories tested",
      "required": true
    },
    {
      "name": "specific_capability",
      "type": "string",
      "description": "Specific capability/tested property (e.g., 'self-replication in VM', 'sycophancy on political topics')",
      "required": true
    },
    {
      "name": "independently_replicated",
      "type": "boolean",
      "description": "Has there been at least one independent replication attempt?",
      "required": true
    },
    {
      "name": "replication_details",
      "type": "object",
      "properties": {
        "replicated_by": {"type": "string"},
        "replication_date": {"type": "string", "format": "date"},
        "replication_link": {"type": "string", "format": "uri"},
        "outcome": {"type": "string", "enum": ["confirmed", "partially-confirmed", "failed", "inconclusive", "in-progress"]},
        "notes": {"type": "string"}
      },
      "required": false
    },
    {
      "name": "open_source",
      "type": "boolean",
      "description": "Is the eval code/runnable artifact publicly available?",
      "required": true
    },
    {
      "name": "runnable",
      "type": "boolean",
      "description": "Can it be run by an independent researcher today (dependencies available, documented)?",
      "required": true
    },
    {
      "name": "compute_requirements",
      "type": "object",
      "properties": {
        "gpu_hours_estimate": {"type": "number"},
        "gpu_type": {"type": "string"},
        "api_only": {"type": "boolean"},
        "notes": {"type": "string"}
      },
      "required": false
    },
    {
      "name": "known_limitations",
      "type": "array",
      "items": {"type": "string"},
      "description": "Known limitations, criticisms, or caveats from creators or community",
      "required": false
    },
    {
      "name": "gap_assessment",
      "type": "string",
      "description": "What related capability is NOT tested by this eval but should be?",
      "required": false
    },
    {
      "name": "source_type",
      "type": "string",
      "enum": ["paper", "blog", "repo", "eval-suite", "interview", "other"],
      "description": "Primary source type",
      "required": true
    },
    {
      "name": "verified_by",
      "type": "string",
      "description": "Who verified this entry (initials/name)",
      "required": true
    },
    {
      "name": "verification_date",
      "type": "string",
      "format": "date",
      "description": "Date this entry was last verified",
      "required": true
    }
  ],
  "example_entry": {
    "eval_id": "arc-autonomous-replication-2024",
    "name": "Autonomous Replication Evaluation",
    "creator_org": "ARC",
    "publication_date": "2024-03-15",
    "link": "https://evals.arc-ai.org/autonomous-replication",
    "capability_categories": ["autonomous-replication", "deception"],
    "specific_capability": "Model attempts to replicate itself across cloud VMs, acquire API keys, and persist",
    "independently_replicated": false,
    "replication_details": null,
    "open_source": true,
    "runnable": true,
    "compute_requirements": {
      "gpu_hours_estimate": 500,
      "gpu_type": "A100",
      "api_only": false,
      "notes": "Requires cloud VM orchestration"
    },
    "known_limitations": [
      "Simulated environment only",
      "No human oversight in loop",
      "Limited to specific cloud provider APIs"
    ],
    "gap_assessment": "No eval tests replication in presence of active monitoring/defense",
    "source_type": "eval-suite",
    "verified_by": "MH",
    "verification_date": "2026-11-16"
  }
}

